function boot(global,data){
  'use strict';
  const doc=global.document,$=id=>doc.getElementById(id),root=$('a181DeploymentMigration');
  if(!root||root.dataset.ready==='1')return;root.dataset.ready='1';
  const KEY='nauka-od-a-do-z-fix181-deployment-migration-refurb-v1';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const read=()=>{try{const x=JSON.parse(global.localStorage.getItem(KEY)||'{}');return{completed:Array.isArray(x.completed)?x.completed:[],notes:x.notes&&typeof x.notes==='object'?x.notes:{},caseScores:x.caseScores&&typeof x.caseScores==='object'?x.caseScores:{},projectChecks:x.projectChecks&&typeof x.projectChecks==='object'?x.projectChecks:{},examHistory:Array.isArray(x.examHistory)?x.examHistory:[],examAnswers:x.examAnswers&&typeof x.examAnswers==='object'?x.examAnswers:{},points:Number(x.points)||0};}catch(_){return{completed:[],notes:{},caseScores:{},projectChecks:{},examHistory:[],examAnswers:{},points:0};}};
  const state=read();let selected=data.lessons[0];
  const status=m=>{if($('a181Status'))$('a181Status').textContent=m;};
  const download=(name,content,type)=>{try{const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=doc.createElement('a');a.href=url;a.download=name;a.style.display='none';doc.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(_){status('Eksport zablokowany przez przeglądarkę.');}};
  const save=()=>{try{global.localStorage.setItem(KEY,JSON.stringify(state));}catch(_){status('Brak miejsca/pamięci lokalnej — wyeksportuj kopię.');}renderProgress();};
  const award=(id,pts,label)=>{const key=`fix181-${id}`;if(state.completed.includes(key))return false;state.completed.push(key);state.points+=pts;try{if(typeof global.ACADEMY_FIX168_AWARD==='function')global.ACADEMY_FIX168_AWARD(key,pts,`FIX181 · ${label}`);else if(typeof global.ACADEMY_FIX168_ADD_JOURNAL==='function')global.ACADEMY_FIX168_ADD_JOURNAL('Akademia wdrożeń FIX181',label,`Ukończono ćwiczenie FIX181; ${pts} pkt.`);}catch(_){}save();return true;};
  const renderProgress=()=>{const lc=state.completed.filter(x=>x.startsWith('fix181-lesson-')).length,cc=Object.keys(state.caseScores).length,pc=Object.values(state.projectChecks).filter(v=>Array.isArray(v)&&v.length>0).length;const set=(id,v)=>{if($(id))$(id).textContent=String(v);};set('a181LessonsDone',`${lc}/${data.lessons.length}`);set('a181CasesDone',`${cc}/${data.cases.length}`);set('a181ProjectsDone',`${pc}/${data.projects.length}`);set('a181ExamDone',state.examHistory.filter(x=>x.passed).length);set('a181Points',state.points);if($('a181Progress'))$('a181Progress').style.width=`${Math.round(lc/data.lessons.length*100)}%`;};
  const cat=$('a181Category');if(cat){[...new Set(data.lessons.map(x=>x.category))].forEach(x=>{const o=doc.createElement('option');o.value=x;o.textContent=x;cat.appendChild(o);});}
  const renderLessonList=()=>{const host=$('a181LessonList');if(!host)return;const q=String($('a181Search')?.value||'').toLocaleLowerCase('pl-PL'),c=$('a181Category')?.value||'all',l=$('a181Level')?.value||'all';const rows=data.lessons.filter(x=>(c==='all'||x.category===c)&&(l==='all'||x.level===l)&&`${x.title} ${x.summary} ${x.category}`.toLocaleLowerCase('pl-PL').includes(q));host.innerHTML=rows.map(x=>`<button type="button" class="a181-lesson ${x.id===selected?.id?'active':''}" data-a181-lesson="${esc(x.id)}"><span>${esc(x.category)} · ${esc(x.level)} · ${x.minutes} min</span><b>${esc(x.title)}</b><small>${esc(x.summary)}</small><em>${state.completed.includes(`fix181-lesson-${x.id}`)?'ZALICZONO':'OTWÓRZ LEKCJĘ'}</em></button>`).join('')||'<p class="a168-note">Brak wyników dla wybranych filtrów.</p>';host.querySelectorAll('[data-a181-lesson]').forEach(b=>b.addEventListener('click',()=>{selected=data.lessons.find(x=>x.id===b.dataset.a181Lesson)||data.lessons[0];renderLessonList();renderLesson();}));};
  const renderLesson=()=>{const host=$('a181LessonDetail');if(!host||!selected)return;const note=state.notes[selected.id]||'';host.innerHTML=`<header class="a181-detail-head"><div><span>${esc(selected.category)} · ${esc(selected.level)}</span><h3>${esc(selected.title)}</h3><p>${esc(selected.summary)}</p></div><b>${selected.minutes} MIN</b></header><div class="a181-columns"><section><h4>Cele nauki</h4><ul>${selected.goals.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Wyjaśnienie techniczne</h4>${selected.theory.map(x=>`<p>${esc(x)}</p>`).join('')}<h4>Procedura serwisowa</h4><ol>${selected.workflow.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h4>Ostrzeżenia i ograniczenia</h4><ul class="a181-warn">${selected.cautions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="a181-sources"><h4>Źródła producenta / standardu</h4>${selected.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`).join('')}</div></section><aside class="a181-note"><h4>Notatki do lekcji</h4><textarea id="a181Note" maxlength="5000" placeholder="Własne notatki — nie wpisuj haseł ani sekretów klienta…">${esc(note)}</textarea><button type="button" class="a168-btn" id="a181SaveNote">Zapisz notatkę</button><p>Notatki są lokalne na tym urządzeniu i wchodzą do kopii FIX181.</p></aside></div><section class="a181-quiz"><h4>Sprawdź wiedzę — 3 pytania</h4>${selected.quiz.map((q,i)=>`<fieldset><legend>${i+1}. ${esc(q.q)}</legend>${q.a.map((a,j)=>`<label><input type="radio" name="a181q${i}" value="${j}"><span>${esc(a)}</span></label>`).join('')}<p hidden id="a181Why${i}"></p></fieldset>`).join('')}<button type="button" class="a168-btn primary" id="a181CheckQuiz">Sprawdź odpowiedzi</button><p id="a181QuizResult" class="a181-result" aria-live="polite">Zaliczenie lekcji wymaga co najmniej 2 poprawnych odpowiedzi.</p></section>`;
    $('a181SaveNote')?.addEventListener('click',()=>{state.notes[selected.id]=$('a181Note').value;save();status('Notatka zapisana lokalnie.');});
    $('a181CheckQuiz')?.addEventListener('click',()=>{let score=0,answered=0;selected.quiz.forEach((q,i)=>{const chosen=host.querySelector(`input[name="a181q${i}"]:checked`);if(chosen)answered++;const ok=chosen&&Number(chosen.value)===q.c;if(ok)score++;const p=$(`a181Why${i}`);p.hidden=false;p.className=ok?'good':'bad';p.textContent=`${ok?'Poprawnie.':'Niepoprawnie.'} ${q.e}`;});if(answered<selected.quiz.length){$('a181QuizResult').textContent=`Uzupełnij wszystkie pytania (${answered}/${selected.quiz.length}).`;return;}const passed=score>=2;if(passed)award(`lesson-${selected.id}`,25,`Lekcja: ${selected.title}`);$('a181QuizResult').textContent=`Wynik: ${score}/${selected.quiz.length}. ${passed?'Lekcja zaliczona.':'Przeczytaj wyjaśnienia i spróbuj ponownie.'}`;renderLessonList();});
  };
  ['a181Search','a181Category','a181Level'].forEach(id=>$(id)?.addEventListener(id==='a181Search'?'input':'change',renderLessonList));
  const caseSelect=$('a181CaseSelect');if(caseSelect){caseSelect.innerHTML=data.cases.map((x,i)=>`<option value="${i}">${esc(x.domain)} — ${esc(x.title)}</option>`).join('');}
  let activeCase=data.cases[0];
  const renderCase=()=>{const host=$('a181CaseBody');if(!host||!activeCase)return;host.innerHTML=`<span class="a181-domain">${esc(activeCase.domain)}</span><h3>${esc(activeCase.title)}</h3><p class="a181-symptom">${esc(activeCase.symptom)}</p>${activeCase.stages.map((s,i)=>`<fieldset class="a181-stage"><legend>${esc(s.name)}</legend><b>${esc(s.prompt)}</b><select id="a181Stage${i}"><option value="">Wybierz odpowiedź…</option>${s.options.map((a,j)=>`<option value="${j}">${esc(a)}</option>`).join('')}</select><p hidden id="a181StageWhy${i}"></p></fieldset>`).join('')}<button type="button" class="a168-btn primary" id="a181EvaluateCase">Oceń przypadek</button><p class="a181-result" id="a181CaseResult" aria-live="polite">Wybierz decyzje na wszystkich trzech etapach.</p>`;host.querySelector('#a181EvaluateCase')?.addEventListener('click',()=>{const answers=activeCase.stages.map((s,i)=>$('a181Stage'+i)?.value);if(answers.some(v=>v==='')){$('a181CaseResult').textContent='Wybierz odpowiedź dla każdego etapu.';return;}let score=0;activeCase.stages.forEach((s,i)=>{const ok=Number(answers[i])===s.correct;if(ok)score++;const p=$('a181StageWhy'+i);p.hidden=false;p.className=ok?'good':'bad';p.textContent=`${ok?'Poprawnie.':'Niepoprawnie.'} ${s.why}`;});const pct=Math.round(score/3*100);state.caseScores[activeCase.id]=Math.max(state.caseScores[activeCase.id]||0,pct);if(pct===100)award(`case-${activeCase.id}`,35,`Przypadek: ${activeCase.title}`);save();$('a181CaseResult').textContent=`Wynik: ${score}/3 (${pct}%). ${pct===100?'Przypadek zaliczony.':'Sprawdź wyjaśnienia i popraw decyzje.'}`;});};
  caseSelect?.addEventListener('change',()=>{activeCase=data.cases[Number(caseSelect.value)]||data.cases[0];renderCase();});renderCase();
  const renderProjects=()=>{const host=$('a181Projects');if(!host)return;host.innerHTML=data.projects.map(p=>{const checks=Array.isArray(state.projectChecks[p.id])?state.projectChecks[p.id]:[];return`<article class="a181-project"><span>${esc(p.category)}</span><h3>${esc(p.title)}</h3>${p.tasks.map((t,i)=>`<label><input type="checkbox" data-a181-project="${esc(p.id)}" data-step="${i}" ${checks.includes(i)?'checked':''}><span>${esc(t)}</span></label>`).join('')}<p><b>Rezultat do oddania:</b> ${esc(p.deliverable)}</p><small>${checks.length}/${p.tasks.length} etapów</small></article>`;}).join('');host.querySelectorAll('[data-a181-project]').forEach(input=>input.addEventListener('change',()=>{const p=data.projects.find(x=>x.id===input.dataset.a181Project),set=new Set(state.projectChecks[p.id]||[]),step=Number(input.dataset.step);input.checked?set.add(step):set.delete(step);state.projectChecks[p.id]=[...set].sort((a,b)=>a-b);if(set.size===p.tasks.length)award(`project-${p.id}`,50,`Projekt: ${p.title}`);save();renderProjects();}));};renderProjects();
  const renderGlossary=()=>{const host=$('a181Glossary');if(!host)return;const q=String($('a181GlossarySearch')?.value||'').toLocaleLowerCase('pl-PL');const rows=data.glossary.filter(([a,b])=>`${a} ${b}`.toLocaleLowerCase('pl-PL').includes(q));host.innerHTML=rows.map(([a,b])=>`<article><b>${esc(a)}</b><span>${esc(b)}</span></article>`).join('')||'<p>Brak terminu.</p>';};$('a181GlossarySearch')?.addEventListener('input',renderGlossary);renderGlossary();
  const examHost=$('a181Exam');if(examHost){examHost.innerHTML=`<p>Egzamin praktyczny FIX181 — 14 pytań z obrazowania Windows, USMT, DFU Mac i odnowy sprzętu. Próg zaliczenia: 80%. Wewnętrzne ćwiczenie szkoleniowe, nie państwowe uprawnienia.</p>${data.exam.map((q,i)=>`<fieldset><legend>${i+1}. ${esc(q.q)}</legend>${q.a.map((a,j)=>`<label><input type="radio" name="a181exam${i}" value="${j}"><span>${esc(a)}</span></label>`).join('')}<p hidden id="a181ExamWhy${i}"></p></fieldset>`).join('')}<button type="button" class="a168-btn primary" id="a181SubmitExam">Zakończ egzamin</button><p class="a181-result" id="a181ExamResult" aria-live="polite">Odpowiedz na wszystkie pytania.</p><div id="a181ExamHistory"></div>`;}
  $('a181SubmitExam')?.addEventListener('click',()=>{let score=0,answered=0;data.exam.forEach((q,i)=>{const x=examHost.querySelector(`input[name="a181exam${i}"]:checked`);if(x)answered++;const ok=x&&Number(x.value)===q.c;if(ok)score++;const p=$('a181ExamWhy'+i);p.hidden=false;p.className=ok?'good':'bad';p.textContent=`${ok?'Poprawnie.':'Niepoprawnie.'} ${q.e}`;});if(answered<data.exam.length){$('a181ExamResult').textContent=`Odpowiedz na wszystkie pytania (${answered}/${data.exam.length}).`;return;}const pct=Math.round(score/data.exam.length*100),passed=pct>=80;state.examHistory.unshift({at:new Date().toISOString(),score:score,total:data.exam.length,pct,passed});state.examHistory=state.examHistory.slice(0,50);if(passed)award('master-exam',100,'Egzamin praktyczny FIX181');save();$('a181ExamResult').textContent=`Wynik: ${score}/${data.exam.length} (${pct}%). ${passed?'Egzamin zaliczony.':'Próg zaliczenia to 80% — przeanalizuj odpowiedzi i ponów próbę.'}`;renderExamHistory();});
  const renderExamHistory=()=>{const h=$('a181ExamHistory');if(!h)return;h.innerHTML=state.examHistory.slice(0,8).map(x=>`<p>${new Date(x.at).toLocaleString('pl-PL')} — ${x.score}/${x.total} (${x.pct}%) · ${x.passed?'ZALICZONY':'NIEZALICZONY'}</p>`).join('');};renderExamHistory();
  $('a181Export')?.addEventListener('click',()=>download('Kopia_Postepow_Akademia_FIX181.json',JSON.stringify({fix:181,productVersion:data.version,exportedAt:new Date().toISOString(),state},null,2),'application/json;charset=utf-8'));
  $('a181Report')?.addEventListener('click',()=>download('Raport_Szkolenia_FIX181.json',JSON.stringify({fix:181,productVersion:data.version,generatedAt:new Date().toISOString(),lessons:data.lessons.length,completedLessons:state.completed.filter(x=>x.startsWith('fix181-lesson-')),cases:data.cases.length,caseScores:state.caseScores,projects:data.projects.length,projectChecks:state.projectChecks,examHistory:state.examHistory,points:state.points,disclaimer:'Wynik szkoleniowy, nie formalne uprawnienia zawodowe.'},null,2),'application/json;charset=utf-8'));
  renderLessonList();renderLesson();renderProgress();status(`FIX181 gotowy: ${data.lessons.length} lekcji, ${data.cases.length} przypadków, ${data.projects.length} projektów, egzamin ${data.exam.length} pytań i ${data.glossary.length} pojęć.`);
}
